mapper.select:
select a.scr_num, group_concat(DISTINCT a.guar_ins_num) AS guar_ins_num, group_concat(DISTINCT b.ins_fn) AS guar_ins_name, group_concat(DISTINCT a.asue_guar_mode_code) AS asue_guar_mode_code, group_concat(DISTINCT a.guar_type_code) AS guar_type_code from v_crdm_inf_bond_guarantor a join v_crdm_inf_inst_archive b on a.guar_ins_num = b.ins_num where 1 = 1
AND (
NULL ) OR a.scr_num IN (#{item}
)
group by a.scr_num

select a.scr_num, listagg(a.guar_ins_num, ',') within group( order by a.guar_ins_num) AS guar_ins_num, listagg(b.ins_fn, ',') within group( order by a.guar_ins_num) AS guar_ins_name, listagg(a.asue_guar_mode_code, ',') within group(order by a.guar_ins_num) AS asue_guar_mode_code, listagg(a.guar_type_code, ',') within group(order by a.guar_ins_num) AS guar_type_code from v_crdm_inf_bond_guarantor a join v_crdm_inf_inst_archive b on a.guar_ins_num = b.ins_num where 1 = 1
AND (
NULL ) OR a.scr_num IN (#{item}
)
group by a.scr_num

select a.scr_num, c.SCR_NAME, a.guar_ins_num AS guar_ins_num, b.ins_fn AS guar_ins_name, a.guar_type_code as asue_guar_mode_code from v_crdm_inf_bond_guarantor a join v_crdm_inf_inst_archive b on a.guar_ins_num = b.ins_num join v_crdm_inf_bond_info c on a.scr_num = c.SCR_NUM
1 = 1
AND (
NULL ) OR a.scr_num IN (#{item}
)

select a.*,b.ins_fn as guar_ins_fn from v_crdm_inf_bond_guarantor a join v_crdm_inf_inst_archive b
on a.guar_ins_num = b.ins_num
and (
    
         NULL ) OR a.scr_num IN (#{item}
    
)

 select b.*  from (
 select a.*,b.ins_fn as guar_ins_fn,c.audt_rat_grad,d.bond_inr_clas,d.issr_num as ins_num,row_number() over(partition by c.scr_num order by c.rat_tect_time desc) mm
 from v_crdm_inf_bond_guarantor a
 inner join v_crdm_inf_inst_archive b on a.guar_ins_num = b.ins_num
 inner join v_crdm_rat_bond_info c on c.scr_num = a.scr_num
 inner join v_crdm_inf_bond_info d on d.scr_num = c.scr_num

    1 = 1
    
        and d.AT_PD_DATE  >=  #{currentDate}
    
    
        AND (
        
             NULL ) OR a.guar_ins_num IN (#{item}
        
        )
    

 ) b
where mm = 1
